"""Arrange actual browser captures. No scene imagery is generated by this script."""
from pathlib import Path
import json
from PIL import Image, ImageDraw, ImageFont

assets = Path(__file__).resolve().parents[1] / 'assets'
names = [('01-source.jpg', '融雪源头'), ('02-stream.jpg', '跌水溪流'),
         ('03-river.jpg', '河谷主河'), ('04-marsh.jpg', '苇泽湿地'),
         ('05-estuary.jpg', '分汊河口'), ('06-bay.jpg', '归水海湾')]
font = ImageFont.truetype('C:/Windows/Fonts/msyh.ttc', 23)
title = ImageFont.truetype('C:/Windows/Fonts/msyh.ttc', 30)
small = ImageFont.truetype('C:/Windows/Fonts/msyh.ttc', 15)
out = Image.new('RGB', (1460, 776), '#edf0e6')
draw = ImageDraw.Draw(out)
draw.text((20, 15), '沿水读群落 · 同一大地图的六站植被', font=title, fill='#244a3d')
draw.text((21, 57), '本机内置浏览器实际运行截图 · 原创程序化场景 · 乔木 / 灌木 / 地被 / 水生四层组合', font=small, fill='#657962')
for i, (file, name) in enumerate(names):
    image = Image.open(assets / 'vegetation-scenes' / file).convert('RGB')
    image.thumbnail((464, 290), Image.Resampling.LANCZOS)
    x, y = 20 + i % 3 * 484, 91 + i // 3 * 337
    out.paste(image, (x, y))
    draw.text((x+7, y+296), f'{i+1:02} · {name}', font=font, fill='#244a3d')
out.save(assets / 'vegetation-world-atlas.jpg', quality=92)
(assets / 'vegetation-scenes' / 'manifest.json').write_text(json.dumps({
    'date': '2026-11-16', 'source': 'actual in-app browser captures',
    'viewport': [1440, 900],
    'scenes': [{'file': f, 'name': n} for f, n in names],
}, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
print('Prepared six actual vegetation scene captures.')

# Three real construction steps, from the same viewpoint with different observation directions.
steps=Image.new('RGB',(1460,430),'#edf0e6')
sd=ImageDraw.Draw(steps)
sd.text((20,14),'同一湿地 · 从生长条件到完整群落',font=title,fill='#244a3d')
sd.text((21,56),'同一观景点，按不同构建对象转向观察 · 地面条件 / 岸上林灌 / 浅水群落',font=small,fill='#657962')
for i,(file,label) in enumerate([('vegetation-step-1-conditions.jpg','01 · 生长条件与留白'),('vegetation-step-2-woodland.jpg','02 · 加入乔木与林下层'),('vegetation-step-3-community.jpg','03 · 补齐地被与水生层')]):
    im=Image.open(assets/file).convert('RGB')
    im.thumbnail((464,290),Image.Resampling.LANCZOS)
    x=20+i*484
    steps.paste(im,(x,91))
    sd.text((x+7,386),label,font=font,fill='#244a3d')
steps.save(assets/'vegetation-construction-steps.jpg',quality=92)
